INSERT INTO "locations" ("id", "name", "slug", "category_id", "subcategory_id", "description", "short_description", "address", "district", "ward", "latitude", "longitude", "phone", "email", "website", "opening_hours", "price_min", "price_max", "price_level", "avg_rating", "review_count", "view_count", "favorite_count", "thumbnail", "images", "video_url", "status", "is_featured", "created_by", "created_at", "updated_at") VALUES
(1, 'Phố cổ Hội An', 'hoi-an-ancient-town', 64, NULL, 'Phố cổ Hội An là một trong những điểm đến hấp dẫn nhất tại Việt Nam, với kiến trúc độc đáo và giá trị văn hóa lịch sử phong phú. Khu phố này nổi bật với những ngôi nhà cổ truyền thống, những con đường nhỏ hẹp và những chiếc đèn lồng màu sắc rực rỡ. Du khách có thể trải nghiệm những hoạt động thú vị như đi dạo quanh phố, tham quan các di tích lịch sử, mua sắm tại các cửa hàng thủ công và thưởng thức ẩm thực địa phương. Thời điểm đẹp nhất để ghé thăm Phố cổ Hội An là vào buổi tối, khi những chiếc đèn lồng được thắp sáng và không khí trở nên lãng mạn. Du khách nên lưu ý về việc mua vé tham quan, trang phục phù hợp và thử các món ăn địa phương như cao lầu, bánh mì và bánh xèo. Ngoài ra, du khách cũng nên khám phá các khu chợ truyền thống và mua một số món quà lưu niệm đặc trưng của Hội An.', 'Phố cổ Hội An là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', 'Phường Minh An, Hội An, Quảng Nam', 'Hội An', NULL, '15.87710000', '108.32650000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '80000.00', '150000.00', 3, '5.00', 4, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563195/danangtrip/locations/hoi-an-ancient-town/loc-1__hoi-an-ancient-town__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563195/danangtrip/locations/hoi-an-ancient-town/loc-1__hoi-an-ancient-town__p01.jpg"]'::jsonb, NULL, 'active', true, 4, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(2, 'Công viên Ấn tượng Hội An', 'hoi-an-memories-land', 52, NULL, 'Công viên Ấn tượng Hội An là một điểm đến lý tưởng tại thành phố cổ kính Hội An, mang đến một trải nghiệm độc đáo và thú vị cho du khách. Với kiến trúc độc đáo và đẹp mắt, công viên này kết hợp hài hòa giữa không gian xanh mát và các hoạt động giải trí đa dạng. Du khách có thể tham gia vào các hoạt động như xem biểu diễn nghệ thuật, tham quan các khu vườn xinh đẹp, hoặc đơn giản là thư giãn và tận hưởng không khí trong lành. Thời điểm đẹp nhất để ghé thăm công viên là vào buổi tối, khi ánh đèn lung linh và không khí trở nên lãng mạn. Để có một chuyến thăm thú vị, du khách nên mua vé trực tuyến trước để tránh chờ đợi, và穿 trang phục thoải mái để tham gia các hoạt động. Ngoài ra, xung quanh công viên có nhiều quán ăn và nhà hàng phục vụ các món ăn địa phương ngon miệng, giúp du khách có một trải nghiệm trọn vẹn và khó quên.', 'Công viên Ấn tượng Hội An là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', 'Cồn Hến, phường Cẩm An, Hội An, Quảng Nam', 'Hội An', NULL, '15.87520000', '108.33940000', NULL, NULL, NULL, '{"fri": "16:00-22:00", "mon": "16:00-22:00", "sat": "16:00-22:00", "sun": "16:00-22:00", "thu": "16:00-22:00", "wed": "16:00-22:00"}'::jsonb, '600000.00', '1200000.00', 4, '4.00', 5, 6, 3, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563198/danangtrip/locations/hoi-an-memories-land/loc-2__hoi-an-memories-land__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563198/danangtrip/locations/hoi-an-memories-land/loc-2__hoi-an-memories-land__p01.jpg"]'::jsonb, NULL, 'active', true, 5, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(3, 'Rừng dừa Bảy Mẫu', 'bay-mau-coconut-forest', 61, NULL, 'Rừng dừa Bảy Mẫu là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Rừng dừa Bảy Mẫu là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Xã Cẩm Thanh, Hội An, Quảng Nam', 'Hội An', NULL, '15.87120000', '108.36450000', NULL, NULL, NULL, '{"fri": "07:00-18:00", "mon": "07:00-18:00", "sat": "07:00-18:00", "sun": "07:00-18:00", "thu": "07:00-18:00", "tue": "07:00-18:00", "wed": "07:00-18:00"}'::jsonb, '150000.00', '300000.00', 3, '4.57', 7, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563200/danangtrip/locations/bay-mau-coconut-forest/loc-3__bay-mau-coconut-forest__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563200/danangtrip/locations/bay-mau-coconut-forest/loc-3__bay-mau-coconut-forest__p01.jpg"]'::jsonb, NULL, 'active', true, 6, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(4, 'Bãi biển Tam Thanh', 'tam-thanh-beach', 7, NULL, 'Bãi biển Tam Thanh là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Bãi biển Tam Thanh là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Xã Tam Thanh, thành phố Tam Kỳ, Quảng Nam', 'Tam Kỳ', NULL, '15.61110000', '108.52220000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '0.00', '0.00', 1, '4.00', 2, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563203/danangtrip/locations/tam-thanh-beach/loc-4__tam-thanh-beach__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563203/danangtrip/locations/tam-thanh-beach/loc-4__tam-thanh-beach__p01.jpg"]'::jsonb, NULL, 'active', false, 7, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(5, 'Bãi biển Bình Minh', 'binh-minh-beach', 7, NULL, 'Bãi biển Bình Minh là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Bãi biển Bình Minh là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Xã Bình Minh, huyện Thăng Bình, Quảng Nam', 'Thăng Bình', NULL, '15.75000000', '108.45000000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '0.00', '0.00', 1, '5.00', 8, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563203/danangtrip/locations/tam-thanh-beach/loc-4__tam-thanh-beach__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563203/danangtrip/locations/tam-thanh-beach/loc-4__tam-thanh-beach__p01.jpg"]'::jsonb, NULL, 'active', false, 8, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(6, 'Cổng Trời Đông Giang', 'dong-giang-heavens-gate', 58, NULL, 'Cổng Trời Đông Giang là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Cổng Trời Đông Giang là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Huyện Đông Giang, Quảng Nam', 'Đông Giang', NULL, '15.95000000', '107.85000000', NULL, NULL, NULL, '{"fri": "08:00-17:00", "mon": "08:00-17:00", "sat": "08:00-17:00", "sun": "08:00-17:00", "thu": "08:00-17:00", "tue": "08:00-17:00", "wed": "08:00-17:00"}'::jsonb, '200000.00', '400000.00', 3, '3.50', 2, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563206/danangtrip/locations/dong-giang-heavens-gate/loc-6__dong-giang-heavens-gate__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563206/danangtrip/locations/dong-giang-heavens-gate/loc-6__dong-giang-heavens-gate__p01.jpg"]'::jsonb, NULL, 'active', false, 9, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(7, 'Quần thể Furama - Ariyana Đà Nẵng', 'furama-ariyana-complex', 55, NULL, 'Quần thể Furama - Ariyana Đà Nẵng là một điểm đến lý tưởng cho du khách khi đến với thành phố biển Đà Nẵng. Với kiến trúc độc đáo và dịch vụ cao cấp, nơi đây mang đến trải nghiệm tuyệt vời cho khách tham quan. Khu phức hợp này bao gồm các khu nghỉ dưỡng, trung tâm hội nghị và các tiện ích giải trí, đáp ứng mọi nhu cầu của du khách. Khi ghé thăm, bạn có thể tận hưởng các hoạt động thú vị như tham gia các buổi hội nghị, thư giãn tại bãi biển riêng hoặc khám phá các điểm du lịch gần đó. Thời điểm đẹp nhất để đến đây là vào mùa hè, khi thời tiết ấm áp và khô ráo, thích hợp cho các hoạt động ngoài trời. Lưu ý, du khách nên đặt phòng và vé tham quan trước để tránh hết chỗ, đồng thời chuẩn bị trang phục phù hợp với các hoạt động và sự kiện tại đây. Ngoài ra, xung quanh khu vực có nhiều nhà hàng và quán ăn địa phương, phục vụ các món ăn đặc sản của Đà Nẵng, giúp du khách có trải nghiệm ẩm thực phong phú.', 'Quần thể Furama - Ariyana Đà Nẵng là địa điểm phục vụ nhu cầu tham quan và trải nghiệm của du khách.', 'Võ Nguyên Giáp, Đà Nẵng', 'Sơn Trà', NULL, '16.03880000', '108.24920000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '3000000.00', '15000000.00', 4, '3.75', 4, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563208/danangtrip/locations/furama-ariyana-complex/loc-7__furama-ariyana-complex__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563208/danangtrip/locations/furama-ariyana-complex/loc-7__furama-ariyana-complex__p01.jpg"]'::jsonb, NULL, 'active', true, 10, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(8, 'Thánh địa Mỹ Sơn', 'my-son-sanctuary', 8, NULL, 'Thánh địa Mỹ Sơn là một trong những di tích lịch sử và văn hóa quan trọng nhất của Việt Nam, nằm ở xã Duy Phú, huyện Duy Xuyên, Quảng Nam. Với kiến trúc độc đáo và giá trị văn hóa sâu sắc, đây là nơi thu hút nhiều du khách trong và ngoài nước. Khi ghé thăm, du khách có thể chiêm ngưỡng những ngôi tháp Chăm Pa cổ kính, khám phá lịch sử và văn hóa của người Chăm, và tham gia vào các hoạt động thú vị như tham quan bảo tàng, xem biểu diễn nghệ thuật truyền thống. Thời điểm đẹp nhất để thăm Thánh địa Mỹ Sơn là vào mùa khô, từ tháng 1 đến tháng 8, khi thời tiết khô ráo và dễ dàng di chuyển. Du khách nên lưu ý mua vé tham quan trước để tránh chờ đợi, và nên mặc trang phục phù hợp với địa điểm tôn giáo. Ngoài ra, xung quanh Thánh địa Mỹ Sơn có nhiều quán ăn và nhà hàng phục vụ ẩm thực địa phương, du khách có thể thưởng thức các món ăn đặc sản như cơm gà, bánh mì, và bánh xèo.', 'Thánh địa Mỹ Sơn là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', 'Xã Duy Phú, huyện Duy Xuyên, Quảng Nam', 'Duy Xuyên', NULL, '15.76380000', '108.12350000', NULL, NULL, NULL, '{"fri": "06:30-17:30", "mon": "06:30-17:30", "sat": "06:30-17:30", "sun": "06:30-17:30", "thu": "06:30-17:30", "tue": "06:30-17:30", "wed": "06:30-17:30"}'::jsonb, '150000.00', '150000.00', 3, '4.33', 6, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563211/danangtrip/locations/my-son-sanctuary/loc-8__my-son-sanctuary__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563211/danangtrip/locations/my-son-sanctuary/loc-8__my-son-sanctuary__p01.jpg"]'::jsonb, NULL, 'active', true, 3, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(9, 'Ghềnh Bàn Than - Hòn Mang', 'ban-than-scenic-area', 7, NULL, 'Ghềnh Bàn Than - Hòn Mang là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Ghềnh Bàn Than - Hòn Mang là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Xã Tam Hải, huyện Núi Thành, Quảng Nam', 'Núi Thành', NULL, '15.45000000', '108.68000000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '0.00', '0.00', 1, '3.00', 1, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563214/danangtrip/locations/ban-than-scenic-area/loc-9__ban-than-scenic-area__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563214/danangtrip/locations/ban-than-scenic-area/loc-9__ban-than-scenic-area__p01.jpg"]'::jsonb, NULL, 'active', false, 4, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(10, 'Hồ Phú Ninh', 'phu-ninh-lake', 57, NULL, 'Hồ Phú Ninh là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Hồ Phú Ninh là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Huyện Phú Ninh, Quảng Nam', 'Phú Ninh', NULL, '15.52000000', '108.45000000', NULL, NULL, NULL, '{"fri": "07:30-17:30", "mon": "07:30-17:30", "sat": "07:30-17:30", "sun": "07:30-17:30", "thu": "07:30-17:30", "tue": "07:30-17:30", "wed": "07:30-17:30"}'::jsonb, '50000.00', '200000.00', 3, '3.33', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563216/danangtrip/locations/phu-ninh-lake/loc-10__phu-ninh-lake__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563216/danangtrip/locations/phu-ninh-lake/loc-10__phu-ninh-lake__p01.jpg"]'::jsonb, NULL, 'active', false, 5, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
