(18, 'Cầu Nguyễn Văn Trỗi', 'nguyen-van-troi-bridge', 7, NULL, 'Cầu Nguyễn Văn Trỗi là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Cầu Nguyễn Văn Trỗi là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Trần Hưng Đạo, Đà Nẵng', 'Sơn Trà', NULL, '16.05200000', '108.22800000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '0.00', '0.00', 1, '4.20', 5, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563237/danangtrip/locations/nguyen-van-troi-bridge/loc-18__nguyen-van-troi-bridge__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563237/danangtrip/locations/nguyen-van-troi-bridge/loc-18__nguyen-van-troi-bridge__p01.jpg"]'::jsonb, NULL, 'active', false, 5, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(19, 'Nhà thờ Chính tòa Đà Nẵng', 'da-nang-cathedral', 11, NULL, 'Nhà thờ Chính tòa Đà Nẵng là một điểm đến nổi bật tại thành phố biển, tọa lạc ở số 156 Trần Phú, thuộc khu vực Hải Châu. Với kiến trúc độc đáo và giá trị văn hóa sâu sắc, nhà thờ này là một trong những công trình kiến trúc tôn giáo đáng chú ý tại Đà Nẵng. Du khách có thể chiêm ngưỡng nét đẹp của nhà thờ qua những đường nét kiến trúc tinh tế, kết hợp giữa phong cách Roman và Gothic, tạo nên một không gian trang nghiêm và thanh tĩnh. Khi ghé thăm, du khách có thể tham gia các hoạt động tôn giáo, hoặc đơn giản là tận hưởng không gian yên bình và chụp ảnh lưu niệm. Thời điểm đẹp nhất để ghé thăm là vào buổi sáng hoặc buổi chiều, khi ánh sáng tự nhiên tạo nên những bức ảnh tuyệt đẹp. Lưu ý, du khách nên mặc trang phục phù hợp và giữ gìn vệ sinh chung khi tham quan nhà thờ. Ngoài ra, xung quanh nhà thờ có nhiều quán ăn và quán cà phê phục vụ du khách, giúp bạn có một trải nghiệm hoàn hảo tại Nhà thờ Chính tòa Đà Nẵng.', 'Nhà thờ Chính tòa Đà Nẵng là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', '156 Trần Phú, Đà Nẵng', 'Hải Châu', NULL, '16.06690000', '108.22310000', NULL, NULL, NULL, '{"fri": "06:00-19:00", "mon": "06:00-19:00", "sat": "06:00-19:00", "sun": "06:00-19:00", "thu": "06:00-19:00", "tue": "06:00-19:00", "wed": "06:00-19:00"}'::jsonb, '0.00', '0.00', 1, '4.00', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563240/danangtrip/locations/da-nang-cathedral/loc-19__da-nang-cathedral__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563240/danangtrip/locations/da-nang-cathedral/loc-19__da-nang-cathedral__p01.jpg"]'::jsonb, NULL, 'active', true, 6, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(20, 'Chùa Linh Ứng Sơn Trà', 'linh-ung-pagoda', 11, NULL, 'Chùa Linh Ứng Sơn Trà là một điểm đến nổi tiếng tại bán đảo Sơn Trà, Đà Nẵng, với kiến trúc độc đáo và vị trí đắc địa. Chùa được xây dựng trên đồi Linh Ứng, với tượng Quan Thế Âm cao 67 mét, là một trong những tượng Phật cao nhất Việt Nam. Du khách có thể tham quan chùa, chiêm bái tượng Phật và thưởng thức cảnh quan tuyệt đẹp của biển Đà Nẵng từ trên cao. Thời điểm đẹp nhất để ghé thăm chùa là vào buổi sáng hoặc buổi chiều, khi ánh nắng không quá mạnh và có thể ngắm nhìn hoàng hôn tuyệt đẹp. Du khách nên mặc trang phục phù hợp và mua vé tham quan với giá hợp lý. Ngoài ra, xung quanh chùa có nhiều quán ăn và cửa hàng lưu niệm, phục vụ nhu cầu của du khách. Với không gian yên tĩnh và cảnh quan tuyệt đẹp, chùa Linh Ứng Sơn Trà là một điểm đến lý tưởng cho những ai muốn tìm kiếm sự bình yên và gần gũi với thiên nhiên.', 'Chùa Linh Ứng Sơn Trà là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', 'Bãi Bụt, bán đảo Sơn Trà, Đà Nẵng', 'Sơn Trà', NULL, '16.10000000', '108.27780000', NULL, NULL, NULL, '{"fri": "06:00-21:00", "mon": "06:00-21:00", "sat": "06:00-21:00", "sun": "06:00-21:00", "thu": "06:00-21:00", "tue": "06:00-21:00", "wed": "06:00-21:00"}'::jsonb, '0.00', '0.00', 1, '3.75', 4, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563243/danangtrip/locations/linh-ung-pagoda/loc-20__linh-ung-pagoda__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563243/danangtrip/locations/linh-ung-pagoda/loc-20__linh-ung-pagoda__p01.jpg"]'::jsonb, NULL, 'active', true, 7, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(21, 'Danh thắng Ngũ Hành Sơn', 'marble-mountains', 9, NULL, 'Danh thắng Ngũ Hành Sơn là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Danh thắng Ngũ Hành Sơn là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Hòa Hải, Đà Nẵng', 'Ngũ Hành Sơn', NULL, '16.00420000', '108.26390000', NULL, NULL, NULL, '{"fri": "07:00-17:30", "mon": "07:00-17:30", "sat": "07:00-17:30", "sun": "07:00-17:30", "thu": "07:00-17:30", "tue": "07:00-17:30", "wed": "07:00-17:30"}'::jsonb, '40000.00', '100000.00', 3, '4.00', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563245/danangtrip/locations/marble-mountains/loc-21__marble-mountains__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563245/danangtrip/locations/marble-mountains/loc-21__marble-mountains__p01.jpg"]'::jsonb, NULL, 'active', true, 8, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(22, 'Công viên Suối khoáng nóng Núi Thần Tài', 'nui-than-tai-park', 16, NULL, 'Công viên Suối khoáng nóng Núi Thần Tài là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Công viên Suối khoáng nóng Núi Thần Tài là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Hòa Phú, Đà Nẵng', 'Hòa Vang', NULL, '15.98000000', '107.98000000', NULL, NULL, NULL, '{"fri": "08:30-17:30", "mon": "08:30-17:30", "sat": "08:30-17:30", "sun": "08:30-17:30", "thu": "08:30-17:30", "tue": "08:30-17:30", "wed": "08:30-17:30"}'::jsonb, '450000.00', '800000.00', 4, '4.20', 5, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563248/danangtrip/locations/nui-than-tai-park/loc-22__nui-than-tai-park__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563248/danangtrip/locations/nui-than-tai-park/loc-22__nui-than-tai-park__p01.jpg"]'::jsonb, NULL, 'active', true, 9, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(23, 'Sun World Bà Nà Hills', 'ba-na-hills', 16, NULL, 'Sun World Bà Nà Hills là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Sun World Bà Nà Hills là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Hòa Ninh, Đà Nẵng', 'Hòa Vang', NULL, '15.99500000', '107.98920000', NULL, NULL, NULL, '{"fri": "07:00-22:00", "mon": "07:00-22:00", "sat": "07:00-22:00", "sun": "07:00-22:00", "thu": "07:00-22:00", "tue": "07:00-22:00", "wed": "07:00-22:00"}'::jsonb, '900000.00', '1500000.00', 4, '5.00', 3, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563251/danangtrip/locations/ba-na-hills/loc-23__ba-na-hills__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563251/danangtrip/locations/ba-na-hills/loc-23__ba-na-hills__p01.jpg"]'::jsonb, NULL, 'active', true, 10, '2026-06-13 10:19:17', '2026-06-14 22:10:25'),
(24, 'Bảo tàng Điêu khắc Chăm Đà Nẵng', 'cham-sculpture-museum', 8, NULL, 'Bảo tàng Điêu khắc Chăm Đà Nẵng là một điểm đến văn hóa nổi bật tại thành phố Đà Nẵng, tọa lạc ở số 02 đường 2 Tháng 9, quận Hải Châu. Với kiến trúc độc đáo và bộ sưu tập hơn 2.000 hiện vật, bảo tàng này trưng bày những tác phẩm điêu khắc Chăm độc đáo, phản ánh cuộc sống và tín ngưỡng của người Chăm. Du khách có thể chiêm ngưỡng những tác phẩm điêu khắc đá, gốm sứ và đồ kim loại, cũng như tìm hiểu về lịch sử và văn hóa của người Chăm. Thời điểm đẹp nhất để ghé thăm là vào buổi sáng hoặc chiều tối, khi ánh sáng không quá mạnh, giúp du khách có thể quan sát rõ hơn các hiện vật. Lưu ý, vé vào cửa khá hợp lý và du khách nên mặc trang phục phù hợp khi tham quan. Ngoài ra, xung quanh bảo tàng có nhiều quán ăn và quán cà phê phục vụ ẩm thực địa phương, giúp du khách có thể tận hưởng trọn vẹn chuyến tham quan.', 'Bảo tàng Điêu khắc Chăm Đà Nẵng là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', '02 đường 2 Tháng 9, quận Hải Châu, Đà Nẵng', 'Hải Châu', NULL, '16.06140000', '108.22360000', NULL, NULL, NULL, '{"fri": "07:30-17:00", "mon": "07:30-17:00", "sat": "07:30-17:00", "sun": "07:30-17:00", "thu": "07:30-17:00", "tue": "07:30-17:00", "wed": "07:30-17:00"}'::jsonb, '60000.00', '60000.00', 2, '4.00', 2, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563253/danangtrip/locations/cham-sculpture-museum/loc-24__cham-sculpture-museum__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563253/danangtrip/locations/cham-sculpture-museum/loc-24__cham-sculpture-museum__p01.jpg"]'::jsonb, NULL, 'active', false, 3, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(25, 'Bảo tàng Đà Nẵng', 'da-nang-museum', 8, NULL, 'Bảo tàng Đà Nẵng là một điểm đến lý tưởng cho những ai yêu thích khám phá lịch sử và văn hóa của thành phố biển. Với kiến trúc độc đáo và hiện đại, bảo tàng này trưng bày hơn 2.000 hiện vật, tài liệu và hình ảnh về lịch sử, văn hóa và cuộc sống của người dân Đà Nẵng. Du khách có thể tham gia các hoạt động thú vị như tham quan triển lãm, xem phim tài liệu, và tham gia các chương trình giáo dục. Thời điểm đẹp nhất để ghé thăm bảo tàng là vào buổi sáng hoặc chiều tối, khi ánh sáng tự nhiên giúp làm nổi bật các hiện vật và không gian trưng bày. Lưu ý, vé vào cửa khá hợp lý và du khách nên mặc trang phục thoải mái để có thể tận hưởng trọn vẹn chuyến thăm. Ngoài ra, xung quanh bảo tàng có nhiều quán ăn và cà phê phục vụ các món ăn địa phương và đồ uống ngon, giúp du khách có thể nghỉ ngơi và thưởng thức ẩm thực sau khi tham quan.', 'Bảo tàng Đà Nẵng là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', '24 Trần Phú, Đà Nẵng', 'Hải Châu', NULL, '16.07500000', '108.22300000', NULL, NULL, NULL, '{"fri": "08:00-17:00", "mon": "08:00-17:00", "sat": "08:00-17:00", "sun": "08:00-17:00", "thu": "08:00-17:00", "tue": "08:00-17:00", "wed": "08:00-17:00"}'::jsonb, '20000.00', '20000.00', 2, '4.67', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563256/danangtrip/locations/da-nang-museum/loc-25__da-nang-museum__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563256/danangtrip/locations/da-nang-museum/loc-25__da-nang-museum__p01.jpg"]'::jsonb, NULL, 'active', false, 4, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(26, 'Bảo tàng Mỹ thuật Đà Nẵng', 'da-nang-fine-arts-museum', 8, NULL, 'Bảo tàng Mỹ thuật Đà Nẵng tọa lạc tại số 78 Lê Duẩn, thuộc khu vực Hải Châu, là một điểm đến văn hóa hấp dẫn và giàu giá trị nghệ thuật. Với kiến trúc độc đáo và hiện đại, bảo tàng này trưng bày một bộ sưu tập đa dạng các tác phẩm mỹ thuật từ các nghệ sĩ trong nước và quốc tế. Du khách có thể chiêm ngưỡng và tìm hiểu về lịch sử phát triển của mỹ thuật Việt Nam thông qua các triển lãm thường xuyên được tổ chức. Khi ghé thăm, du khách có thể tham gia các hoạt động thú vị như tham quan triển lãm, học vẽ và tham gia các buổi nói chuyện về nghệ thuật. Thời điểm đẹp nhất để ghé thăm là vào buổi sáng hoặc chiều tối khi ánh sáng tự nhiên giúp làm nổi bật các tác phẩm nghệ thuật. Lưu ý, vé vào cửa có giá phải chăng và du khách nên mặc trang phục thoải mái để có thể tận hưởng không gian nghệ thuật một cách trọn vẹn. Ngoài ra, xung quanh bảo tàng cũng có nhiều quán cà phê và nhà hàng phục vụ ẩm thực địa phương đa dạng.', 'Bảo tàng Mỹ thuật Đà Nẵng là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', '78 Lê Duẩn, Đà Nẵng', 'Hải Châu', NULL, '16.07200000', '108.22100000', NULL, NULL, NULL, '{"fri": "08:00-17:00", "mon": "08:00-17:00", "sat": "08:00-17:00", "sun": "08:00-17:00", "thu": "08:00-17:00", "tue": "08:00-17:00", "wed": "08:00-17:00"}'::jsonb, '20000.00', '20000.00', 2, '4.67', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563259/danangtrip/locations/da-nang-fine-arts-museum/loc-26__da-nang-fine-arts-museum__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563259/danangtrip/locations/da-nang-fine-arts-museum/loc-26__da-nang-fine-arts-museum__p01.jpg"]'::jsonb, NULL, 'active', false, 5, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(27, 'Bảo tàng Hồ Chí Minh - Chi nhánh Quân khu 5', 'ho-chi-minh-museum', 8, NULL, 'Bảo tàng Hồ Chí Minh - Chi nhánh Quân khu 5 là một điểm đến hấp dẫn tại Đà Nẵng, nằm ở địa chỉ 01 Duy Tân, thuộc khu vực Hải Châu. Với kiến trúc độc đáo và giá trị văn hóa, lịch sử phong phú, bảo tàng này trưng bày nhiều hiện vật và tài liệu quý giá về cuộc đời và sự nghiệp của Chủ tịch Hồ Chí Minh, cũng như lịch sử quân khu 5. Khi ghé thăm, du khách có thể tham gia các hoạt động thú vị như tham quan triển lãm, nghe thuyết minh về các hiện vật và tham gia các chương trình giáo dục. Thời điểm đẹp nhất để thăm bảo tàng là vào buổi sáng hoặc chiều tối, khi ánh sáng tự nhiên giúp làm nổi bật kiến trúc và hiện vật. Du khách nên lưu ý về việc mua vé và trang phục phù hợp khi tham quan, cũng như khám phá ẩm thực địa phương xung quanh bảo tàng.', 'Bảo tàng Hồ Chí Minh - Chi nhánh Quân khu 5 là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', '01 Duy Tân, Đà Nẵng', 'Hải Châu', NULL, '16.05000000', '108.22000000', NULL, NULL, NULL, '{"fri": "07:30-16:30", "mon": "07:30-16:30", "sat": "07:30-16:30", "sun": "07:30-16:30", "thu": "07:30-16:30", "tue": "07:30-16:30", "wed": "07:30-16:30"}'::jsonb, '20000.00', '20000.00', 2, '5.00', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563262/danangtrip/locations/ho-chi-minh-museum/loc-27__ho-chi-minh-museum__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563262/danangtrip/locations/ho-chi-minh-museum/loc-27__ho-chi-minh-museum__p01.jpg"]'::jsonb, NULL, 'active', false, 6, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(28, 'Bảo tàng Đồng Đình', 'dong-dinh-museum', 8, NULL, 'Bảo tàng Đồng Đình là một điểm đến độc đáo tại Sơn Trà, Đà Nẵng, nơi trưng bày và giới thiệu về nghệ thuật điêu khắc đồng và các sản phẩm thủ công mỹ nghệ truyền thống. Với kiến trúc độc đáo và không gian trưng bày rộng rãi, bảo tàng mang đến cho du khách một trải nghiệm văn hóa và nghệ thuật phong phú. Du khách có thể tham gia các hoạt động thú vị như xem biểu diễn điêu khắc đồng, học cách tạo ra các sản phẩm thủ công mỹ nghệ, và khám phá các bộ sưu tập đồng độc đáo. Thời điểm đẹp nhất để ghé thăm là vào buổi sáng hoặc buổi chiều khi ánh sáng tự nhiên giúp làm nổi bật các sản phẩm trưng bày. Du khách nên lưu ý về giá vé vào cửa và nên mặc trang phục thoải mái để có thể tham gia các hoạt động một cách tiện lợi. Ngoài ra, xung quanh bảo tàng cũng có nhiều quán ăn và quán cà phê phục vụ các món ăn địa phương và đồ uống đặc trưng, giúp du khách có một trải nghiệm hoàn hảo.', 'Bảo tàng Đồng Đình là điểm tham quan văn hóa, lịch sử đáng chú ý tại miền Trung.', 'Sơn Trà, Đà Nẵng', 'Sơn Trà', NULL, '16.11000000', '108.27000000', NULL, NULL, NULL, '{"fri": "08:00-17:00", "mon": "08:00-17:00", "sat": "08:00-17:00", "sun": "08:00-17:00", "thu": "08:00-17:00", "tue": "08:00-17:00", "wed": "08:00-17:00"}'::jsonb, '20000.00', '20000.00', 2, '4.25', 4, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563265/danangtrip/locations/dong-dinh-museum/loc-28__dong-dinh-museum__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563265/danangtrip/locations/dong-dinh-museum/loc-28__dong-dinh-museum__p01.jpg"]'::jsonb, NULL, 'active', false, 7, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(29, 'Công viên Châu Á - Asia Park', 'asia-park', 16, NULL, 'Công viên Châu Á - Asia Park là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Công viên Châu Á - Asia Park là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', '01 Phan Đăng Lưu, quận Hải Châu, Đà Nẵng', 'Hải Châu', NULL, '16.03920000', '108.22720000', NULL, NULL, NULL, '{"fri": "15:00-22:00", "mon": "15:00-22:00", "sat": "15:00-22:00", "sun": "15:00-22:00", "thu": "15:00-22:00", "tue": "15:00-22:00", "wed": "15:00-22:00"}'::jsonb, '200000.00', '500000.00', 4, '5.00', 3, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563268/danangtrip/locations/asia-park/loc-29__asia-park__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563268/danangtrip/locations/asia-park/loc-29__asia-park__p01.jpg"]'::jsonb, NULL, 'active', true, 8, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(30, 'Công viên Biển Đông', 'east-sea-park', 10, NULL, 'Công viên Biển Đông là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Công viên Biển Đông là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Võ Nguyên Giáp, Đà Nẵng', 'Sơn Trà', NULL, '16.07100000', '108.24400000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '0.00', '0.00', 1, '5.00', 2, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563271/danangtrip/locations/east-sea-park/loc-30__east-sea-park__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563271/danangtrip/locations/east-sea-park/loc-30__east-sea-park__p01.jpg"]'::jsonb, NULL, 'active', false, 9, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(31, 'Công viên APEC', 'apec-park', 10, NULL, 'Công viên APEC là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Công viên APEC là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', '2 Tháng 9, Đà Nẵng', 'Hải Châu', NULL, '16.06000000', '108.22500000', NULL, NULL, NULL, '{"fri": "00:00-23:59", "mon": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59", "thu": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59"}'::jsonb, '0.00', '0.00', 1, '4.40', 5, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563274/danangtrip/locations/apec-park/loc-31__apec-park__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563274/danangtrip/locations/apec-park/loc-31__apec-park__p01.jpg"]'::jsonb, NULL, 'active', true, 10, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(32, 'Công viên 29/3', '29-3-park', 10, NULL, 'Công viên 29/3 là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Công viên 29/3 là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Đường Điện Biên Phủ, quận Thanh Khê, Đà Nẵng', 'Thanh Khê', NULL, '16.06500000', '108.21000000', NULL, NULL, NULL, '{"fri": "05:00-22:00", "mon": "05:00-22:00", "sat": "05:00-22:00", "sun": "05:00-22:00", "thu": "05:00-22:00", "tue": "05:00-22:00", "wed": "05:00-22:00"}'::jsonb, '0.00', '0.00', 1, '4.67', 6, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563276/danangtrip/locations/29-3-park/loc-32__29-3-park__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563276/danangtrip/locations/29-3-park/loc-32__29-3-park__p01.jpg"]'::jsonb, NULL, 'active', false, 3, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(33, 'Bánh Xèo 76', 'banh-xeo-76', 1, NULL, 'Bánh Xèo 76 là một điểm đến ẩm thực nổi tiếng tại khu vực Ngũ Hành Sơn, Đà Nẵng, nằm ở địa chỉ 85A Lê Văn Hưu. Nơi đây nổi tiếng với món bánh xèo giòn rụm, nóng hổi, phục vụ cùng với rau sống tươi ngon và nước mắm đậm đà. Khi ghé thăm, du khách có thể tận hưởng không gian ấm cúng và gần gũi, được thiết kế đơn giản nhưng mang lại cảm giác thoải mái. Một kinh nghiệm thú vị khi đến Bánh Xèo 76 là được tự tay cuốn bánh xèo với rau sống và nước mắm, tạo nên một trải nghiệm ẩm thực độc đáo. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi không gian trở nên ấm áp và lãng mạn. Du khách nên lưu ý gọi điện đặt chỗ trước để tránh chờ đợi, và có thể kết hợp thăm quan các địa điểm du lịch gần đó như Chùa Linh Ứng hoặc Bãi biển Mỹ Khê.', 'Bánh Xèo 76 là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '85A Lê Văn Hưu, quận Ngũ Hành Sơn, Đà Nẵng', 'Ngũ Hành Sơn', NULL, '16.04000000', '108.24000000', NULL, NULL, NULL, '{"fri": "10:00-21:00", "mon": "10:00-21:00", "sat": "10:00-21:00", "sun": "10:00-21:00", "thu": "10:00-21:00", "tue": "10:00-21:00", "wed": "10:00-21:00"}'::jsonb, '50000.00', '150000.00', 3, '4.67', 3, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563279/danangtrip/locations/banh-xeo-76/loc-33__banh-xeo-76__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563279/danangtrip/locations/banh-xeo-76/loc-33__banh-xeo-76__p01.jpg"]'::jsonb, NULL, 'active', false, 4, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(34, 'Bún Bò Huế Bà Thương', 'bun-bo-hue-ba-thuong', 1, NULL, 'Bún Bò Huế Bà Thương tọa lạc tại 23 Trần Quốc Toản, quận Hải Châu, Đà Nẵng, là một điểm đến ẩm thực nổi tiếng và đặc sắc. Với kiến trúc đơn giản nhưng ấm cúng, quán mang đến một không gian thoải mái cho thực khách. Nét đặc sắc của Bún Bò Huế Bà Thương nằm ở công thức nấu bún bò truyền thống, với nước dùng đậm đà và thịt bò mềm, tạo nên một hương vị khó quên. Khi ghé thăm, bạn có thể thưởng thức bún bò vào bất kỳ thời điểm nào trong ngày, nhưng buổi sáng và buổi trưa là thời điểm lý tưởng nhất. Lưu ý, quán thường đông vào giờ ăn trưa, vì vậy bạn nên đến sớm để có trải nghiệm tốt nhất. Ngoài ra, xung quanh quán có nhiều điểm ăn uống và mua sắm, giúp bạn có một ngày khám phá đầy đủ và thú vị.', 'Bún Bò Huế Bà Thương là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '23 Trần Quốc Toản, quận Hải Châu, Đà Nẵng', 'Hải Châu', NULL, '16.06500000', '108.22000000', NULL, NULL, NULL, '{"fri": "06:00-21:00", "mon": "06:00-21:00", "sat": "06:00-21:00", "sun": "06:00-21:00", "thu": "06:00-21:00", "tue": "06:00-21:00", "wed": "06:00-21:00"}'::jsonb, '40000.00', '100000.00', 3, '4.33', 3, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563599/danangtrip/locations/bun-bo-hue-ba-thuong/loc-34__bun-bo-hue-ba-thuong__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563599/danangtrip/locations/bun-bo-hue-ba-thuong/loc-34__bun-bo-hue-ba-thuong__p01.jpg"]'::jsonb, NULL, 'active', false, 5, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(35, 'Nhà hàng Quê Xưa', 'que-xua-restaurant', 1, NULL, 'Nhà hàng Quê Xưa tọa lạc tại 116 Núi Thành, quận Hải Châu, Đà Nẵng, là điểm đến lý tưởng cho những ai muốn trải nghiệm ẩm thực truyền thống Việt Nam. Với kiến trúc mang đậm nét văn hóa quê hương, nhà hàng mang đến một không gian ấm cúng và gần gũi. Khi ghé thăm, bạn có thể thưởng thức các món ăn đặc sản của vùng miền, từ những món ăn dân dã đến những món ăn cầu kỳ, tất cả đều được chế biến từ những nguyên liệu tươi ngon và được trình bày đẹp mắt. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi nhà hàng được trang trí bởi ánh đèn ấm áp và không gian trở nên lãng mạn. Lưu ý, bạn nên đặt chỗ trước để đảm bảo có chỗ ngồi, và hãy thử những món ăn đặc sản của nhà hàng như bánh xèo, bánh cuốn, và các loại hải sản tươi sống.', 'Nhà hàng Quê Xưa là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '116 Núi Thành, quận Hải Châu, Đà Nẵng', 'Hải Châu', NULL, '16.04500000', '108.22000000', NULL, NULL, NULL, '{"fri": "10:00-22:00", "mon": "10:00-22:00", "sat": "10:00-22:00", "sun": "10:00-22:00", "thu": "10:00-22:00", "tue": "10:00-22:00", "wed": "10:00-22:00"}'::jsonb, '100000.00', '500000.00', 4, '4.67', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563285/danangtrip/locations/que-xua-restaurant/loc-35__que-xua-restaurant__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563285/danangtrip/locations/que-xua-restaurant/loc-35__que-xua-restaurant__p01.jpg"]'::jsonb, NULL, 'active', false, 6, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(36, 'Nhà hàng chay Shamballa', 'shamballa-vegetarian', 1, NULL, 'Nhà hàng chay Shamballa tọa lạc tại số 277 Trần Hưng Đạo, Đà Nẵng, thuộc khu vực Sơn Trà, là điểm đến lý tưởng cho những ai yêu thích ẩm thực chay và tìm kiếm không gian yên tĩnh. Với kiến trúc độc đáo và trang trí ấm cúng, nhà hàng mang đến một trải nghiệm ẩm thực đặc biệt. Thực đơn đa dạng với các món chay ngon và bổ dưỡng, được chế biến từ nguyên liệu tươi ngon, đảm bảo mang lại cho bạn một bữa ăn здоров và hài lòng. Khi ghé thăm, bạn có thể tận hưởng không gian yên bình và thưởng thức các món ăn chay trong một bầu không khí ấm cúng. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi nhà hàng được trang trí bằng ánh đèn ấm áp. Lưu ý, nhà hàng có thể có giờ mở cửa và thực đơn thay đổi, vì vậy bạn nên kiểm tra trước khi đến. Ngoài ra, khu vực xung quanh cũng có nhiều điểm du lịch hấp dẫn, giúp bạn có một chuyến du lịch đầy đủ và thú vị.', 'Nhà hàng chay Shamballa là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '277 Trần Hưng Đạo, Đà Nẵng', 'Sơn Trà', NULL, '16.06000000', '108.23000000', NULL, NULL, NULL, '{"fri": "10:00-22:00", "mon": "10:00-22:00", "sat": "10:00-22:00", "sun": "10:00-22:00", "thu": "10:00-22:00", "tue": "10:00-22:00", "wed": "10:00-22:00"}'::jsonb, '100000.00', '400000.00', 3, '4.00', 1, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563287/danangtrip/locations/shamballa-vegetarian/loc-36__shamballa-vegetarian__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563287/danangtrip/locations/shamballa-vegetarian/loc-36__shamballa-vegetarian__p01.jpg"]'::jsonb, NULL, 'active', false, 7, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(37, 'Bếp Cuốn', 'bep-cuon', 1, NULL, 'Bếp Cuốn tọa lạc tại 31 Trần Bạch Đằng, quận Ngũ Hành Sơn, Đà Nẵng, là một điểm đến lý tưởng cho những ai yêu thích ẩm thực và không gian ấm cúng. Nét đặc sắc của Bếp Cuốn nằm ở kiến trúc độc đáo, kết hợp giữa phong cách hiện đại và truyền thống, tạo nên một không gian ấm áp và gần gũi. Khi ghé thăm, du khách có thể trải nghiệm các hoạt động thú vị như tham gia lớp học nấu ăn, tìm hiểu về văn hóa ẩm thực địa phương, và thưởng thức các món ăn đặc sản. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi không gian trở nên lãng mạn và ấm áp với ánh đèn ấm. Du khách nên lưu ý về việc đặt chỗ trước để đảm bảo chỗ ngồi, và có thể tận hưởng các món ăn địa phương xung quanh khu vực Ngũ Hành Sơn.', 'Bếp Cuốn là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '31 Trần Bạch Đằng, quận Ngũ Hành Sơn, Đà Nẵng', 'Ngũ Hành Sơn', NULL, '16.05000000', '108.24500000', NULL, NULL, NULL, '{"fri": "10:30-21:30", "mon": "10:30-21:30", "sat": "10:30-21:30", "sun": "10:30-21:30", "thu": "10:30-21:30", "tue": "10:30-21:30", "wed": "10:30-21:30"}'::jsonb, '50000.00', '200000.00', 3, '4.63', 8, 6, 3, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563290/danangtrip/locations/bep-cuon/loc-37__bep-cuon__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563290/danangtrip/locations/bep-cuon/loc-37__bep-cuon__p01.jpg"]'::jsonb, NULL, 'active', false, 8, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(38, 'Bún Riêu Cua 39', 'bun-rieu-cua-39', 1, NULL, 'Bún Riêu Cua 39 là một điểm đến ẩm thực nổi tiếng tại Đà Nẵng, tọa lạc ở số 39 Lê Hồng Phong, quận Hải Châu. Nơi đây nổi tiếng với món bún riêu cua đậm đà, phong phú và tươi ngon, thu hút nhiều du khách và người dân địa phương. Khi ghé thăm, bạn có thể trải nghiệm không gian ấm cúng và gần gũi, với đội ngũ nhân viên phục vụ tận tình. Thời điểm đẹp nhất để ghé thăm là vào buổi sáng hoặc trưa, khi món ăn còn nóng hổi và tươi ngon. Lưu ý, bạn nên đến sớm để tránh chờ đợi, và có thể thử thêm các món ăn khác như bánh cuốn, bánh ướt, hoặc các loại nước uống địa phương. Giá cả hợp lý và chất lượng món ăn tuyệt vời, Bún Riêu Cua 39 là một điểm đến lý tưởng cho những ai yêu thích ẩm thực đường phố Đà Nẵng.', 'Bún Riêu Cua 39 là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '39 Lê Hồng Phong, quận Hải Châu, Đà Nẵng', 'Hải Châu', NULL, '16.06500000', '108.22200000', NULL, NULL, NULL, '{"fri": "06:00-13:00", "mon": "06:00-13:00", "sat": "06:00-13:00", "sun": "06:00-13:00", "thu": "06:00-13:00", "tue": "06:00-13:00", "wed": "06:00-13:00"}'::jsonb, '30000.00', '60000.00', 2, '4.00', 2, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563292/danangtrip/locations/bun-rieu-cua-39/loc-38__bun-rieu-cua-39__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563292/danangtrip/locations/bun-rieu-cua-39/loc-38__bun-rieu-cua-39__p01.jpg"]'::jsonb, NULL, 'active', false, 9, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(39, 'Nhà hàng Mộc', 'moc-restaurant', 1, NULL, 'Nhà hàng Mộc tọa lạc tại 26 Tô Hiến Thành, quận Sơn Trà, Đà Nẵng, là điểm đến lý tưởng cho những ai yêu thích ẩm thực và kiến trúc độc đáo. Với phong cách thiết kế mộc mạc, gần gũi với thiên nhiên, nhà hàng mang đến một không gian ấm cúng và thoải mái cho thực khách. Khi ghé thăm, bạn có thể thưởng thức các món ăn địa phương và quốc tế được chế biến từ nguyên liệu tươi ngon, trong không gian yên tĩnh và lãng mạn. Buổi tối là thời điểm đẹp nhất để đến Nhà hàng Mộc, khi ánh đèn ấm áp và tiếng nhạc du dương tạo nên một bầu không khí lãng mạn. Lưu ý, nhà hàng có phục vụ rượu và đồ uống, vì vậy bạn nên chọn trang phục phù hợp và đặt chỗ trước để đảm bảo chỗ ngồi. Ngoài ra, xung quanh nhà hàng cũng có nhiều quán cà phê và cửa hàng lưu niệm thú vị để bạn khám phá.', 'Nhà hàng Mộc là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '26 Tô Hiến Thành, quận Sơn Trà, Đà Nẵng', 'Sơn Trà', NULL, '16.05500000', '108.24200000', NULL, NULL, NULL, '{"fri": "10:00-23:00", "mon": "10:00-23:00", "sat": "10:00-23:00", "sun": "10:00-23:00", "thu": "10:00-23:00", "tue": "10:00-23:00", "wed": "10:00-23:00"}'::jsonb, '150000.00', '1000000.00', 4, '5.00', 2, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563295/danangtrip/locations/moc-restaurant/loc-39__moc-restaurant__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563295/danangtrip/locations/moc-restaurant/loc-39__moc-restaurant__p01.jpg"]'::jsonb, NULL, 'active', false, 10, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(40, 'La Maison 1888', 'la-maison-1888', 2, NULL, 'La Maison 1888 là một điểm đến độc đáo tại InterContinental Khu nghỉ dưỡng, Sơn Trà, mang đến trải nghiệm ẩm thực Pháp tinh tế và sang trọng. Với kiến trúc cổ điển kết hợp phong cách hiện đại, nhà hàng này tạo nên một không gian ấm cúng và lãng mạn. Du khách có thể thưởng thức các món ăn Pháp truyền thống được chế biến bởi đầu bếp nổi tiếng, cùng với danh sách rượu vang phong phú. Ghé thăm La Maison 1888 vào buổi tối để cảm nhận không gian lãng mạn với ánh đèn ấm áp và view nhìn ra biển tuyệt đẹp. Du khách nên đặt chỗ trước để đảm bảo chỗ ngồi lý tưởng. Trang phục trang nhã và lịch sự là yêu cầu khi đến với La Maison 1888. Ngoài ra, du khách cũng có thể khám phá các hoạt động giải trí và dịch vụ xung quanh khu nghỉ dưỡng, như đi dạo trên bãi biển, tham gia các lớp học nấu ăn hoặc thư giãn tại spa.', 'La Maison 1888 là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', 'InterContinental Khu nghỉ dưỡng, Sơn Trà', 'Sơn Trà', NULL, '16.12000000', '108.31000000', NULL, NULL, NULL, '{"fri": "18:00-22:00", "mon": "18:00-22:00", "sat": "18:00-22:00", "sun": "18:00-22:00", "thu": "18:00-22:00", "tue": "18:00-22:00", "wed": "18:00-22:00"}'::jsonb, '2000000.00', '10000000.00', 4, '4.00', 4, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563297/danangtrip/locations/la-maison-1888/loc-40__la-maison-1888__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563297/danangtrip/locations/la-maison-1888/loc-40__la-maison-1888__p01.jpg"]'::jsonb, NULL, 'active', true, 3, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(41, 'Nén Đà Nẵng', 'nen-danang', 2, NULL, 'Nén Đà Nẵng là một điểm đến lý tưởng cho những ai yêu thích khám phá văn hóa và lịch sử của thành phố Đà Nẵng. Với kiến trúc độc đáo và giá trị văn hóa phong phú, Nén Đà Nẵng mang đến một trải nghiệm thú vị và đáng nhớ. Khi ghé thăm, du khách có thể tham gia vào các hoạt động như tham quan bảo tàng, tìm hiểu về lịch sử và văn hóa của địa phương, cũng như thưởng thức các món ăn đặc sản của vùng. Thời điểm đẹp nhất để ghé thăm Nén Đà Nẵng là vào buổi sáng hoặc buổi chiều, khi ánh sáng vàng ấm áp tạo nên một khung cảnh tuyệt đẹp. Du khách nên lưu ý về việc mua vé tham quan và trang phục phù hợp để có một trải nghiệm trọn vẹn. Ngoài ra, xung quanh Nén Đà Nẵng cũng có nhiều quán ăn và nhà hàng phục vụ các món ăn địa phương, giúp du khách có thể thưởng thức và khám phá ẩm thực của vùng.', 'Nén Đà Nẵng là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '16 Mỹ Đa Tây 2, quận Ngũ Hành Sơn, Đà Nẵng', 'Ngũ Hành Sơn', NULL, '16.03500000', '108.24500000', NULL, NULL, NULL, '{"fri": "18:00-22:00", "mon": "18:00-22:00", "sat": "18:00-22:00", "sun": "18:00-22:00", "thu": "18:00-22:00", "tue": "18:00-22:00", "wed": "18:00-22:00"}'::jsonb, '1500000.00', '3500000.00', 4, '4.33', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563300/danangtrip/locations/nen-danang/loc-41__nen-danang__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563300/danangtrip/locations/nen-danang/loc-41__nen-danang__p01.jpg"]'::jsonb, NULL, 'active', true, 4, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(42, 'Pizza 4P''s Hoàng Văn Thụ', 'pizza-4p-hoang-van-thu', 2, NULL, 'Pizza 4P''s Hoàng Văn Thụ là một điểm đến lý tưởng cho những người yêu thích ẩm thực Ý tại Đà Nẵng. Với kiến trúc hiện đại và ấm cúng, nhà hàng mang đến một không gian thoải mái cho thực khách. Nét đặc sắc của Pizza 4P''s là sự kết hợp giữa nguyên liệu tươi ngon và công thức nấu ăn độc đáo, tạo nên những món pizza ngon miệng và hấp dẫn. Khi ghé thăm, bạn có thể tận hưởng hoạt động thú vị như tự tay làm pizza hoặc tham gia các chương trình khuyến mãi hấp dẫn. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi nhà hàng được trang trí bằng ánh đèn ấm áp và không gian trở nên lãng mạn. Lưu ý, bạn nên đặt chỗ trước để tránh chờ đợi, và đừng quên thử các món ăn phụ như salad và món tráng miệng để có trải nghiệm hoàn hảo.', 'Pizza 4P''s Hoàng Văn Thụ là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '08 Hoàng Văn Thụ, quận Hải Châu, Đà Nẵng', 'Hải Châu', NULL, '16.06800000', '108.22350000', NULL, NULL, NULL, '{"fri": "11:00-22:00", "mon": "11:00-22:00", "sat": "11:00-22:00", "sun": "11:00-22:00", "thu": "11:00-22:00", "tue": "11:00-22:00", "wed": "11:00-22:00"}'::jsonb, '200000.00', '800000.00', 4, '3.00', 1, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563303/danangtrip/locations/pizza-4p-hoang-van-thu/loc-42__pizza-4p-hoang-van-thu__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563303/danangtrip/locations/pizza-4p-hoang-van-thu/loc-42__pizza-4p-hoang-van-thu__p01.jpg"]'::jsonb, NULL, 'active', true, 5, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(43, 'Nhà hàng Madame Lân', 'madam-lan', 1, NULL, 'Nhà hàng Madame Lân tọa lạc tại số 04 Bạch Đằng, Đà Nẵng, thuộc khu vực Hải Châu, là điểm đến lý tưởng cho những ai yêu thích ẩm thực phong phú và không gian ấm cúng. Với kiến trúc độc đáo và trang trí tinh tế, nhà hàng mang đến một trải nghiệm ẩm thực đặc sắc, kết hợp giữa phong cách truyền thống và hiện đại. Khi ghé thăm, bạn có thể tận hưởng các món ăn đa dạng, từ hải sản tươi sống đến các món ăn địa phương đặc trưng, tất cả đều được chế biến bởi đội ngũ đầu bếp chuyên nghiệp. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi nhà hàng được thắp sáng bởi ánh đèn ấm áp, tạo nên một bầu không khí lãng mạn và ấm cúng. Lưu ý, bạn nên đặt chỗ trước để đảm bảo chỗ ngồi, đặc biệt là vào các dịp lễ hoặc cuối tuần. Ngoài ra, nhà hàng cũng cung cấp dịch vụ giao hàng và đặt hàng trực tuyến, giúp bạn dễ dàng thưởng thức ẩm thực ngon miệng ngay tại nhà.', 'Nhà hàng Madame Lân là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '04 Bạch Đằng, Đà Nẵng', 'Hải Châu', NULL, '16.08200000', '108.22200000', NULL, NULL, NULL, '{"fri": "06:30-21:30", "mon": "06:30-21:30", "sat": "06:30-21:30", "sun": "06:30-21:30", "thu": "06:30-21:30", "tue": "06:30-21:30", "wed": "06:30-21:30"}'::jsonb, '100000.00', '600000.00', 4, '4.25', 4, 4, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563305/danangtrip/locations/madam-lan/loc-43__madam-lan__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563305/danangtrip/locations/madam-lan/loc-43__madam-lan__p01.jpg"]'::jsonb, NULL, 'active', true, 6, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(44, 'Waterfront Đà Nẵng', 'waterfront-danang', 2, NULL, 'Waterfront Đà Nẵng tọa lạc tại 150 Bạch Đằng, Đà Nẵng, thuộc khu vực Hải Châu, là điểm đến lý tưởng cho những ai yêu thích kiến trúc hiện đại và không gian mở. Với thiết kế độc đáo và sang trọng, Waterfront Đà Nẵng mang đến một trải nghiệm tuyệt vời cho du khách. Du khách có thể tham gia các hoạt động thú vị như đi dạo沿 bờ sông, ngắm nhìn cảnh quan thành phố, hoặc tham gia các sự kiện văn hóa và giải trí. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi thành phố lên đèn và không gian trở nên lãng mạn. Du khách nên lưu ý về việc mua vé tham quan, cũng như trang phục phù hợp với hoạt động và thời tiết. Ngoài ra, khu vực xung quanh có nhiều nhà hàng và quán cà phê phục vụ các món ăn địa phương và quốc tế, giúp du khách có thể tận hưởng trọn vẹn chuyến đi.', 'Waterfront Đà Nẵng là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '150 Bạch Đằng, Đà Nẵng', 'Hải Châu', NULL, '16.06800000', '108.22400000', NULL, NULL, NULL, '{"fri": "10:00-23:00", "mon": "10:00-23:00", "sat": "10:00-23:00", "sun": "10:00-23:00", "thu": "10:00-23:00", "tue": "10:00-23:00", "wed": "10:00-23:00"}'::jsonb, '200000.00', '1500000.00', 4, '4.67', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563308/danangtrip/locations/waterfront-danang/loc-44__waterfront-danang__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563308/danangtrip/locations/waterfront-danang/loc-44__waterfront-danang__p01.jpg"]'::jsonb, NULL, 'active', false, 7, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(45, 'Fatfish Đà Nẵng', 'fat-fish-da-nang', 2, NULL, 'Fatfish Đà Nẵng tọa lạc tại số 439 Trần Hưng Đạo, thuộc khu vực Sơn Trà, là một điểm đến lý tưởng cho những ai yêu thích ẩm thực và không gian biển. Với kiến trúc hiện đại và trang trí tinh tế, Fatfish mang đến một trải nghiệm độc đáo và thoải mái cho du khách. Khi ghé thăm, bạn có thể tận hưởng những món ăn hải sản tươi sống và đa dạng, cùng với đó là không gian view biển tuyệt đẹp. Thời điểm đẹp nhất để ghé thăm Fatfish là vào buổi tối, khi ánh đèn lung linh và không khí trở nên lãng mạn. Lưu ý, bạn nên đặt chỗ trước để đảm bảo chỗ ngồi, đặc biệt là vào cuối tuần. Ngoài ra, khu vực xung quanh cũng có nhiều quán ăn và cửa hàng lưu niệm, giúp bạn có một chuyến du lịch đầy đủ và thú vị.', 'Fatfish Đà Nẵng là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '439 Trần Hưng Đạo, Đà Nẵng', 'Sơn Trà', NULL, '16.06000000', '108.23500000', NULL, NULL, NULL, '{"fri": "10:00-22:30", "mon": "10:00-22:30", "sat": "10:00-22:30", "sun": "10:00-22:30", "thu": "10:00-22:30", "tue": "10:00-22:30", "wed": "10:00-22:30"}'::jsonb, '150000.00', '800000.00', 4, '5.00', 3, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563310/danangtrip/locations/fat-fish-da-nang/loc-45__fat-fish-da-nang__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563310/danangtrip/locations/fat-fish-da-nang/loc-45__fat-fish-da-nang__p01.jpg"]'::jsonb, NULL, 'active', false, 8, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(46, 'Le Rendez-Vous', 'le-rendez-vous', 2, NULL, 'Le Rendez-Vous tọa lạc tại 20 Lý Thường Kiệt, quận Hải Châu, Đà Nẵng, là điểm đến lý tưởng cho những ai yêu thích kiến trúc Pháp cổ điển và không gian lãng mạn. Với nét đặc sắc nổi bật là kiến trúc độc đáo, Le Rendez-Vous mang đến một trải nghiệm độc đáo và thú vị cho du khách. Khi ghé thăm, bạn có thể tham gia vào các hoạt động thú vị như thưởng thức cà phê và bánh ngọt trong không gian ấm cúng, hoặc tham gia các buổi biểu diễn âm nhạc sống động vào buổi tối. Thời điểm đẹp nhất để ghé thăm Le Rendez-Vous là vào buổi chiều tối, khi không gian được chiếu sáng bởi đèn ấm áp và tạo nên một bầu không khí lãng mạn. Lưu ý, bạn nên mặc trang phục lịch sự và thoải mái để có thể tận hưởng trọn vẹn không gian tại đây. Ngoài ra, xung quanh Le Rendez-Vous cũng có nhiều quán ăn và nhà hàng địa phương phục vụ các món ăn truyền thống Đà Nẵng, giúp bạn có một trải nghiệm ẩm thực phong phú và đa dạng.', 'Le Rendez-Vous là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '20 Lý Thường Kiệt, quận Hải Châu, Đà Nẵng', 'Hải Châu', NULL, '16.07600000', '108.22000000', NULL, NULL, NULL, '{"fri": "11:00-22:00", "mon": "11:00-22:00", "sat": "11:00-22:00", "sun": "11:00-22:00", "thu": "11:00-22:00", "tue": "11:00-22:00", "wed": "11:00-22:00"}'::jsonb, '300000.00', '2000000.00', 4, '5.00', 2, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563313/danangtrip/locations/le-rendez-vous/loc-46__le-rendez-vous__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563313/danangtrip/locations/le-rendez-vous/loc-46__le-rendez-vous__p01.jpg"]'::jsonb, NULL, 'active', false, 9, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(47, 'Red Sky Steakhouse', 'red-sky-steakhouse', 2, NULL, 'Red Sky Steakhouse tọa lạc tại 248 Trần Phú, Đà Nẵng, là điểm đến lý tưởng cho những ai yêu thích ẩm thực phong cách Tây và không gian ấm cúng. Với kiến trúc hiện đại và trang trí tinh tế, nhà hàng mang đến một trải nghiệm ẩm thực cao cấp. Thực đơn đa dạng với các món steak được chế biến từ những nguyên liệu tươi ngon, cùng với rượu vang và cocktail được pha chế bởi những bartender chuyên nghiệp. Khi ghé thăm, bạn có thể tận hưởng không gian lãng mạn vào buổi tối hoặc tổ chức các bữa tiệc với bạn bè và gia đình. Lưu ý nên đặt chỗ trước để đảm bảo chỗ ngồi, đặc biệt là vào cuối tuần. Trang phục lịch sự cũng là một lưu ý khi đến với Red Sky Steakhouse. Khu vực xung quanh cũng có nhiều quán cà phê và cửa hàng thời trang để bạn khám phá trước hoặc sau bữa ăn.', 'Red Sky Steakhouse là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '248 Trần Phú, Đà Nẵng', 'Hải Châu', NULL, '16.06300000', '108.22300000', NULL, NULL, NULL, '{"fri": "11:00-23:00", "mon": "11:00-23:00", "sat": "11:00-23:00", "sun": "11:00-23:00", "thu": "11:00-23:00", "tue": "11:00-23:00", "wed": "11:00-23:00"}'::jsonb, '500000.00', '3000000.00', 4, '4.40', 5, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563316/danangtrip/locations/red-sky-steakhouse/loc-47__red-sky-steakhouse__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563316/danangtrip/locations/red-sky-steakhouse/loc-47__red-sky-steakhouse__p01.jpg"]'::jsonb, NULL, 'active', false, 10, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(48, 'Burger Bros', 'burger-bros', 2, NULL, 'Burger Bros tọa lạc tại 31 An Thượng 4, Đà Nẵng, thuộc khu vực Ngũ Hành Sơn, là điểm đến lý tưởng cho những người yêu thích ẩm thực đường phố và đặc biệt là bánh burger. Với kiến trúc hiện đại và phong cách trẻ trung, Burger Bros mang đến một không gian năng động và thoải mái cho khách hàng. Khi ghé thăm, bạn có thể tận hưởng những chiếc bánh burger ngon miệng với nhiều loại nhân khác nhau, từ thịt bò đến gà và chay, tất cả đều được chế biến tươi ngon. Thời điểm đẹp nhất để ghé thăm là vào buổi tối, khi không gian trở nên ấm cúng và lãng mạn với ánh đèn ấm áp. Lưu ý, bạn nên đặt chỗ trước để tránh chờ đợi, và đừng quên thử các món ăn phụ và đồ uống đặc biệt của quán. Khu vực xung quanh cũng có nhiều điểm thú vị để khám phá, như chùa Linh Ứng và biển Mỹ Khê, giúp bạn có một trải nghiệm du lịch đa dạng và phong phú.', 'Burger Bros là địa điểm ẩm thực phù hợp để tham khảo khi khám phá Đà Nẵng và khu vực miền Trung.', '31 An Thượng 4, Đà Nẵng', 'Ngũ Hành Sơn', NULL, '16.05000000', '108.24600000', NULL, NULL, NULL, '{"fri": "11:00-21:00", "mon": "11:00-21:00", "sat": "11:00-21:00", "sun": "11:00-21:00", "thu": "11:00-21:00", "tue": "11:00-21:00", "wed": "11:00-21:00"}'::jsonb, '100000.00', '300000.00', 3, '4.25', 4, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563319/danangtrip/locations/burger-bros/loc-48__burger-bros__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563319/danangtrip/locations/burger-bros/loc-48__burger-bros__p01.jpg"]'::jsonb, NULL, 'active', false, 3, '2026-06-13 10:19:17', '2026-06-14 15:03:23'),
(49, 'Nhà hàng Sofia', 'sofia-restaurant', 1, NULL, 'Nhà hàng Sofia tọa lạc tại Lô 1-2 Phạm Văn Đồng, quận Sơn Trà, Đà Nẵng, là điểm đến lý tưởng cho những ai yêu thích ẩm thực phong phú và không gian ấm cúng. Với kiến trúc hiện đại và trang trí tinh tế, nhà hàng mang đến một trải nghiệm ẩm thực đặc sắc. Du khách có thể thưởng thức các món ăn đa dạng, từ hải sản tươi sống đến các món ăn truyền thống Việt Nam, tất cả đều được chế biến bởi đội ngũ đầu bếp chuyên nghiệp.
