(111, 'Làng rau Trà Quế', 'tra-que-vegetable-village', 61, NULL, 'Làng rau Trà Quế là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Làng rau Trà Quế là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Làng Trà Quế, phường Cẩm Hà, Hội An, Quảng Nam', 'Hội An', NULL, '15.89930000', '108.33730000', NULL, NULL, NULL, NULL, NULL, NULL, 1, '4.40', 5, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563511/danangtrip/locations/perfume-river/loc-111__perfume-river__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563511/danangtrip/locations/perfume-river/loc-111__perfume-river__p01.jpg"]'::jsonb, NULL, 'active', false, NULL, '2026-06-13 10:20:13', '2026-06-14 15:03:23'),
(112, 'Phá Tam Giang', 'tam-giang-lagoon', 7, NULL, 'Phá Tam Giang là điểm đến phù hợp để kết hợp trong lịch trình khám phá Đà Nẵng, Hội An, Quảng Nam và thành phố Huế. Thời tiết, vé tham quan và giờ hoạt động nên được kiểm tra trước chuyến đi.', 'Phá Tam Giang là điểm tham quan và trải nghiệm nổi bật trong hành trình khám phá miền Trung.', 'Phá Tam Giang, thành phố Huế', 'Huế', NULL, '16.60000000', '107.63330000', NULL, NULL, NULL, NULL, NULL, NULL, 1, '4.00', 2, 3, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780563513/danangtrip/locations/han-river/loc-112__han-river__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780563513/danangtrip/locations/han-river/loc-112__han-river__p01.jpg"]'::jsonb, NULL, 'active', false, NULL, '2026-06-13 10:20:13', '2026-06-14 15:03:23'),
(113, 'Điểm lưu trú Nguyễn Đức Chung', 'diem-luu-tru-nguyen-duc-chung', 6, NULL, 'Điểm lưu trú Nguyễn Đức Chung tọa lạc tại 139 Nguyễn Đức Chung, Đà Nẵng, là một điểm đến lý tưởng cho những ai đang tìm kiếm một nơi nghỉ dưỡng thoải mái và tiện nghi. Với kiến trúc hiện đại và trang thiết bị đầy đủ, điểm lưu trú này mang đến cho du khách một không gian sống ấm cúng và gần gũi. Du khách có thể tận hưởng các hoạt động thú vị như đi dạo沿 bãi biển, tham quan các địa điểm du lịch nổi tiếng của Đà Nẵng hoặc đơn giản là thư giãn trong không gian yên tĩnh của điểm lưu trú. Thời điểm đẹp nhất để ghé thăm là vào mùa hè, khi thời tiết ấm áp và nắng vàng chiếu sáng khắp thành phố. Du khách nên lưu ý về việc đặt phòng trước để đảm bảo chỗ ở và có thể tận hưởng các dịch vụ tiện ích như wifi miễn phí, phòng gym, và nhà hàng trong khuôn viên. Ngoài ra, du khách cũng có thể khám phá ẩm thực địa phương với các nhà hàng và quán ăn gần điểm lưu trú, phục vụ các món ăn đặc sản của Đà Nẵng.', 'Điểm lưu trú Nguyễn Đức Chung là cơ sở lưu trú phục vụ du khách tại Đà Nẵng và khu vực miền Trung.', '139 Nguyễn Đức Chung, Đà Nẵng', 'Đà Nẵng', NULL, '16.46900000', '107.58000000', NULL, NULL, NULL, NULL, NULL, NULL, 1, '0.00', 0, 0, 0, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780559596/danangtrip/locations/kon-tiki-hostel/loc-210__kon-tiki-hostel__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780559596/danangtrip/locations/kon-tiki-hostel/loc-210__kon-tiki-hostel__p01.jpg"]'::jsonb, NULL, 'active', false, NULL, '2026-06-13 10:20:13', '2026-06-14 15:03:23'),
(114, '4 Seasons Danang Hostel', '4-seasons-danang-hostel', 6, NULL, '4 Seasons Danang Hostel tọa lạc tại 69 Châu Thị Vĩnh Tế, quận Ngũ Hành Sơn, Đà Nẵng, là một điểm đến lý tưởng cho những ai đang tìm kiếm một không gian nghỉ dưỡng thoải mái và gần gũi. Với kiến trúc hiện đại và trang thiết bị đầy đủ, hostel này mang đến cho du khách một trải nghiệm lưu trú tuyệt vời. Du khách có thể tận hưởng các hoạt động thú vị như tham gia tour du lịch thành phố, thăm các địa điểm nổi tiếng gần đó hoặc đơn giản là thư giãn tại hostel với các tiện ích như phòng khách chung, khu vực nấu nướng và sân hiên. Thời điểm đẹp nhất để ghé thăm là vào mùa hè, khi thời tiết ấm áp và khô ráo, thích hợp cho các hoạt động ngoài trời. Khi đến đây, du khách nên lưu ý về việc đặt phòng sớm để đảm bảo chỗ, cũng như khám phá các quán ăn và cửa hàng xung quanh để trải nghiệm ẩm thực địa phương.', '4 Seasons Danang Hostel là cơ sở lưu trú phục vụ du khách tại Đà Nẵng và khu vực miền Trung.', '69 Châu Thị Vĩnh Tế, quận Ngũ Hành Sơn, Đà Nẵng', 'Ngũ Hành Sơn', NULL, '16.07000000', '108.22500000', NULL, NULL, NULL, NULL, NULL, NULL, 1, '0.00', 0, 0, 0, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780559283/danangtrip/locations/4-seasons-danang-hostel/loc-114__4-seasons-danang-hostel__p01.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780559283/danangtrip/locations/4-seasons-danang-hostel/loc-114__4-seasons-danang-hostel__p01.jpg"]'::jsonb, NULL, 'active', false, NULL, '2026-06-13 10:20:13', '2026-06-14 15:03:23')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, category_id = EXCLUDED.category_id, address = EXCLUDED.address, description = EXCLUDED.description, short_description = EXCLUDED.short_description, thumbnail = EXCLUDED.thumbnail, images = EXCLUDED.images, status = EXCLUDED.status, updated_at = NOW();

